from abc import ABC
from frost_sta_client.service.sensorthingsservice import SensorThingsService


class Entity(ABC):
    """
    An abstract representation of an entity.
    """
    def __init__(self,
                 id=None,
                 self_link='',
                 service=None):
        self.id = id
        self.self_link = self_link
        self.service = service

    @property
    def id(self):
        return self._id

    @id.setter
    def id(self, value):
        if value is None:
            self._id = None
            return
        if isinstance(value, int) or isinstance(value, str):
            self._id = value
            return
        raise ValueError('id of entity should be of type int or str!')

    @property
